-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_transactions_1k AS SELECT transactions_1k.TransactionID AS TransactionID, transactions_1k.Date AS Date, transactions_1k.Time AS Time, transactions_1k.CustomerID AS CustomerID, transactions_1k.CardID AS CardID, transactions_1k.GasStationID AS GasStationID, transactions_1k.ProductID AS ProductID, transactions_1k.Amount AS Amount, transactions_1k.Price AS Price, Customer.Segment AS Segment, Customer.Currency AS Currency, GasStation.ChainID AS ChainID, GasStation.Country AS Country, GasStation.Segment AS GasStation_Segment, Product.Description AS Description FROM transactions_1k LEFT JOIN customers AS Customer ON transactions_1k.CustomerID = Customer.CustomerID LEFT JOIN gasstations AS GasStation ON transactions_1k.GasStationID = GasStation.GasStationID LEFT JOIN products AS Product ON transactions_1k.ProductID = Product.ProductID;

-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_yearmonth AS SELECT yearmonth.CustomerID AS CustomerID, yearmonth.Date AS Date, yearmonth.Consumption AS Consumption, Customer.Segment AS Segment, Customer.Currency AS Currency FROM yearmonth LEFT JOIN customers AS Customer ON yearmonth.CustomerID = Customer.CustomerID;
